import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const ReservationForm = () => {
  const [formData, setFormData] = useState({
    dateRetrait: '',
    heureRetrait: '10:00',
    dateRetour: '',
    heureRetour: '10:00',
    transmission: 'Manuelle',
    siege: '4',
    categorie: 'Berline',
    carburant: 'Diesel'
  });

  const [results, setResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const navigate = useNavigate();

  const mockCars = [
    { id: 1, modele: 'Peugeot 208', categorie: 'Compacte', transmission: 'Manuelle', siege: '5', carburant: 'Essence', prix: 120, image: 'peugeot208.jpg' },
    { id: 2, modele: 'Renault Clio', categorie: 'Compacte', transmission: 'Manuelle', siege: '5', carburant: 'Diesel', prix: 110, image: 'clio.jpg' },
    { id: 3, modele: 'Volkswagen Golf', categorie: 'Berline', transmission: 'Automatique', siege: '5', carburant: 'Essence', prix: 150, image: 'golf.jpg' },
    { id: 4, modele: 'Toyota RAV4', categorie: 'SUV', transmission: 'Automatique', siege: '5', carburant: 'Hybride', prix: 180, image: 'rav4.jpg' }
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSearching(true);
    
    setTimeout(() => {
      const filteredCars = mockCars.filter(car => {
        return (
          car.transmission === formData.transmission &&
          car.siege >= formData.siege &&
          car.categorie === formData.categorie &&
          car.carburant === formData.carburant
        );
      });
      
      setResults(filteredCars);
      setIsSearching(false);
      
      // Scroll to results
      document.getElementById('results-section').scrollIntoView({ behavior: 'smooth' });
    }, 500);
  };

  const handleReservation = (carId) => {
    localStorage.setItem('selectedCar', JSON.stringify(
      mockCars.find(car => car.id === carId)
    ));
    navigate('/confirmation');
  };

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const defaultReturnDate = new Date();
    defaultReturnDate.setDate(defaultReturnDate.getDate() + 2);
    const defaultReturnDateStr = defaultReturnDate.toISOString().split('T')[0];
    
    setFormData(prev => ({
      ...prev,
      dateRetrait: today,
      dateRetour: defaultReturnDateStr
    }));
  }, []);

  return (
    <div className="max-w-4xl mx-auto p-4 bg-white rounded-lg shadow-md">
      <h1 className="text-xl font-bold mb-2 text-center">Réservation de véhicule</h1>
      <h2 className="text-md font-semibold mb-4 text-center text-blue-600">Aéroport Tunis Carthage</h2>
      
      <form onSubmit={handleSubmit} className="mb-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div className="bg-gray-50 p-3 rounded-lg">
            <h3 className="font-medium mb-2 text-sm">Période de location</h3>
            <div className="grid grid-cols-1 gap-2">
              <div>
                <label className="block text-xs font-medium mb-1">Date de retrait*</label>
                <input
                  type="date"
                  name="dateRetrait"
                  value={formData.dateRetrait}
                  onChange={handleChange}
                  min={new Date().toISOString().split('T')[0]}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Heure de retrait*</label>
                <input
                  type="time"
                  name="heureRetrait"
                  value={formData.heureRetrait}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Date de retour*</label>
                <input
                  type="date"
                  name="dateRetour"
                  value={formData.dateRetour}
                  onChange={handleChange}
                  min={formData.dateRetrait}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Heure de retour*</label>
                <input
                  type="time"
                  name="heureRetour"
                  value={formData.heureRetour}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                  required
                />
              </div>
            </div>
          </div>

          <div className="bg-gray-50 p-3 rounded-lg">
            <h3 className="font-medium mb-2 text-sm">Préférences du véhicule</h3>
            <div className="grid grid-cols-1 gap-2">
              <div>
                <label className="block text-xs font-medium mb-1">Transmission</label>
                <select
                  name="transmission"
                  value={formData.transmission}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                >
                  <option value="Manuelle">Manuelle</option>
                  <option value="Automatique">Automatique</option>
                  <option value="Semi-automatique">Semi-automatique</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Sièges</label>
                <select
                  name="siege"
                  value={formData.siege}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                >
                  {[2, 4, 5, 7, 9].map(num => (
                    <option key={num} value={num}>{num} sièges</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Catégorie</label>
                <select
                  name="categorie"
                  value={formData.categorie}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                >
                  <option value="Economique">Economique</option>
                  <option value="Compacte">Compacte</option>
                  <option value="Berline">Berline</option>
                  <option value="SUV">SUV</option>
                  <option value="Monospace">Monospace</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">Carburant</label>
                <select
                  name="carburant"
                  value={formData.carburant}
                  onChange={handleChange}
                  className="w-full p-1 text-sm border rounded focus:ring-1 focus:ring-blue-500"
                >
                  <option value="Essence">Essence</option>
                  <option value="Diesel">Diesel</option>
                  <option value="Electrique">Electrique</option>
                  <option value="Hybride">Hybride</option>
                  <option value="GPL">GPL</option>
                </select>
              </div>
            </div>
          </div>
        </div>

        <div className="text-center">
          <button
            type="submit"
            disabled={isSearching}
            className={`w-full md:w-1/2 py-2 px-4 rounded text-sm text-white font-medium shadow transition-colors ${
              isSearching ? 'bg-blue-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'
            }`}
          >
            {isSearching ? 'Recherche...' : 'Rechercher'}
          </button>
        </div>
      </form>

      {isSearching && (
        <div className="text-center py-4">
          <div className="inline-block animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-blue-500"></div>
        </div>
      )}

      <div id="results-section">
        {results.length > 0 && !isSearching && (
          <div className="mt-4">
            <h3 className="text-lg font-bold mb-2">Résultats</h3>
            <div className="overflow-x-auto">
              <table className="min-w-full bg-white border border-gray-200 text-sm">
                <thead className="bg-gray-100">
                  <tr>
                    <th className="py-2 px-3 border-b text-left">Modèle</th>
                    <th className="py-2 px-3 border-b text-left">Catégorie</th>
                    <th className="py-2 px-3 border-b text-left">Prix/jour</th>
                    <th className="py-2 px-3 border-b text-left">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map(car => (
                    <tr key={car.id} className="hover:bg-gray-50">
                      <td className="py-2 px-3 border-b">{car.modele}</td>
                      <td className="py-2 px-3 border-b">{car.categorie}</td>
                      <td className="py-2 px-3 border-b">{car.prix} €</td>
                      <td className="py-2 px-3 border-b">
                        <button
                          onClick={() => handleReservation(car.id)}
                          className="bg-green-500 hover:bg-green-600 text-white py-1 px-2 rounded text-xs"
                        >
                          Réserver
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {results.length === 0 && !isSearching && (
          <div className="text-center py-4 text-gray-500 text-sm">
            Aucun véhicule trouvé
          </div>
        )}
      </div>
    </div>
  );
};

export default ReservationForm;
